using UpInBlue.Leonardo.Check.Checkers;

namespace UpInBlue.Leonardo.Check;

/// <summary>
/// The rules of one language.
/// </summary>
internal interface IChecker
{
    /// <summary>
    /// Adds the findings of <paramref name="source"/> to <paramref name="findings"/>.
    /// </summary>
    void Check(SourceText source, FindingList findings);
}

/// <summary>
/// Checks files: picks the rules by file extension and skips generated files.
/// </summary>
internal static class LeonardoChecker
{
    /// <summary>
    /// The file extensions the tool checks.
    /// </summary>
    public static IReadOnlySet<string> Extensions { get; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".xaml", ".cs", ".swift", ".css", ".scss", ".html", ".htm", ".tsx",
    };

    /// <summary>
    /// Folder names whose content is generated, built or downloaded, and never checked.
    /// </summary>
    public static IReadOnlySet<string> SkippedFolders { get; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "Generated", "bin", "obj", "node_modules", "packages", "Pods", "DerivedData", ".build",
    };

    /// <summary>
    /// Whether a path can be checked: a known extension, outside generated and build folders, not a generated file name.
    /// </summary>
    public static bool IsCandidate(string path)
    {
        if (!Extensions.Contains(Path.GetExtension(path)))
        {
            return false;
        }

        var name = Path.GetFileName(path);
        if (name.EndsWith(".g.cs", StringComparison.OrdinalIgnoreCase)
            || name.EndsWith(".g.i.cs", StringComparison.OrdinalIgnoreCase)
            || name.EndsWith(".designer.cs", StringComparison.OrdinalIgnoreCase)
            || name.Contains(".generated.", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (IsTestFileName(name))
        {
            return false;
        }

        var segments = path.Split(['/', '\\'], StringSplitOptions.RemoveEmptyEntries);
        return !segments.Take(segments.Length - 1).Any(segment => SkippedFolders.Contains(segment) || IsTestFolder(segment));
    }

    /// <summary>
    /// Test code is not UI: tests hold literal values on purpose, for example to check contrast. Folders named
    /// <c>test</c>, <c>tests</c> or <c>__tests__</c>, or ending in <c>Tests</c> (.NET test projects, Swift test
    /// targets), are skipped.
    /// </summary>
    public static bool IsTestFolder(string name)
        => name.Equals("test", StringComparison.OrdinalIgnoreCase)
            || name.Equals("tests", StringComparison.OrdinalIgnoreCase)
            || name.Equals("__tests__", StringComparison.OrdinalIgnoreCase)
            || (name.Length > "Tests".Length && name.EndsWith("Tests", StringComparison.Ordinal));

    private static bool IsTestFileName(string name)
        => name.EndsWith(".test.tsx", StringComparison.OrdinalIgnoreCase)
            || name.EndsWith(".spec.tsx", StringComparison.OrdinalIgnoreCase)
            || name.EndsWith("Tests.swift", StringComparison.Ordinal)
            || name.EndsWith("Tests.cs", StringComparison.Ordinal);

    /// <summary>
    /// Whether the text of a file says it is generated: <c>&lt;auto-generated</c>, or "Generated by" together with
    /// "Do not edit" in its first lines, as in the files of the Leonardo token generator.
    /// </summary>
    public static bool HasGeneratedHeader(string text)
    {
        var head = string.Join('\n', text.Split('\n').Take(8));
        return head.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase)
            || (head.Contains("Generated by", StringComparison.OrdinalIgnoreCase) && head.Contains("Do not edit", StringComparison.OrdinalIgnoreCase));
    }

    /// <summary>
    /// Checks the text of one file. Returns no findings for generated files and unknown extensions.
    /// </summary>
    /// <param name="displayPath">The path shown in the output; its extension selects the rules.</param>
    /// <param name="text">The content of the file.</param>
    public static IReadOnlyList<Finding> Check(string displayPath, string text)
    {
        if (!IsCandidate(displayPath) || HasGeneratedHeader(text))
        {
            return [];
        }

        var extension = Path.GetExtension(displayPath).ToLowerInvariant();
        var code = extension is ".cs" or ".swift" ? SourceText.MaskCodeComments(text, blankStrings: true) : null;
        var (masked, checker) = extension switch
        {
            ".xaml" => (SourceText.MaskMarkupComments(text), (IChecker)new XamlChecker()),
            ".cs" => (SourceText.MaskCodeComments(text), new CSharpChecker()),
            ".swift" => (SourceText.MaskCodeComments(text), new SwiftChecker()),
            ".css" or ".scss" => (SourceText.MaskCodeComments(text, lineComments: Path.GetExtension(displayPath).Equals(".scss", StringComparison.OrdinalIgnoreCase)), new WebChecker(WebLanguage.Css)),
            ".html" or ".htm" => (SourceText.MaskMarkupComments(text), new WebChecker(WebLanguage.Html)),
            ".tsx" => (SourceText.MaskCodeComments(text), new WebChecker(WebLanguage.Tsx)),
            _ => throw new InvalidOperationException("Unreachable: the extension was checked above."),
        };

        var source = new SourceText(displayPath, text, masked, code);
        var findings = new FindingList(source);
        checker.Check(source, findings);
        return [.. findings.Items.OrderBy(f => f.Line).ThenBy(f => f.Rule.Id, StringComparer.Ordinal)];
    }

    /// <summary>
    /// Checks files and folders. Folders are searched recursively; hidden folders (starting with a dot) and the
    /// <see cref="SkippedFolders"/> are left out.
    /// </summary>
    /// <param name="paths">Files and folders.</param>
    /// <param name="baseDirectory">The directory that output paths are relative to.</param>
    public static IReadOnlyList<Finding> CheckPaths(IEnumerable<string> paths, string baseDirectory)
    {
        var findings = new List<Finding>();
        foreach (var file in paths.SelectMany(Enumerate).Distinct(StringComparer.OrdinalIgnoreCase).Order(StringComparer.Ordinal))
        {
            var display = Path.GetRelativePath(baseDirectory, file).Replace('\\', '/');
            findings.AddRange(Check(display, File.ReadAllText(file)));
        }

        return findings;
    }

    private static IEnumerable<string> Enumerate(string path)
    {
        var full = Path.GetFullPath(path);
        if (File.Exists(full))
        {
            if (IsCandidate(full))
            {
                yield return full;
            }

            yield break;
        }

        if (!Directory.Exists(full))
        {
            throw new FileNotFoundException($"No file or folder at {path}.", path);
        }

        var pending = new Stack<string>([full]);
        while (pending.Count > 0)
        {
            var directory = pending.Pop();
            foreach (var file in Directory.EnumerateFiles(directory))
            {
                if (Extensions.Contains(Path.GetExtension(file)) && IsCandidate(Path.GetFileName(file)))
                {
                    yield return file;
                }
            }

            foreach (var child in Directory.EnumerateDirectories(directory))
            {
                var name = Path.GetFileName(child);
                if (!name.StartsWith('.') && !SkippedFolders.Contains(name) && !IsTestFolder(name))
                {
                    pending.Push(child);
                }
            }
        }
    }
}
